import {AFTERLIGHT_FLAGS,AFTERLIGHT_CODE,AFTERLIGHT_HINTS,AFTERLIGHT_THINGS,afterlightStage} from './afterlight-world.mjs';
const blank=()=>({active:false,kind:null,time:0,cleared:false});
export function createAfterlight({emit,mark,reward}){
 const say=(s,text)=>emit(s,'expedition-message',{text});
 const living=s=>s.drones.filter(b=>b.afterlight&&b.hp>0);
 function clearActors(s){s.drones=s.drones.filter(b=>!b.afterlight);s.bullets=s.bullets.filter(b=>!b.afterlight);}
 function init(s){s.expedition.afterlight=blank();}
 function spawn(s,kind){clearActors(s);const roof=kind==='roof',y=roof?27.5:7,points=roof?[[-111,-13],[-103,-14]]:[[-74,-12],[-84,-12]];
  s.expedition.afterlight={active:true,kind,time:0,cleared:false};
  points.forEach(([x,z],i)=>s.drones.push({id:'afterlight-'+kind+'-'+i,afterlight:true,kind:i?'marshal':'warden',home:'bellmarket',arenaHome:roof?{x:-107,z:-9,w:14,d:16}:{x:-93,z:-18,w:48,d:40},x,y:y+1.05,z,origin:{x,y:y+1.05,z},hp:roof?65:55,maxHp:roof?65:55,reward:0,humanoid:true,heading:0,patrol:[[x,z],[x,z+1.3]],patrolIndex:0,attack:3+i*.6,attackDelay:roof?3.5:4,shotDamage:9,projectileSpeed:16,stun:0,telegraph:0,awareness:0,chaseSpeed:1.8}));
  emit(s,'afterlight-encounter',{kind});
 }
 function abort(s,reason='interrupted'){const run=s.expedition.afterlight;if(run?.active){say(s,'Afterlight '+run.kind+' encounter '+reason+'. Return to its fuse or rooftop console to retry; recovered components are safe.');}clearActors(s);s.expedition.afterlight=blank();}
 function handle(s,id){if(!id.startsWith('afterlight-'))return false;const stage=afterlightStage(s),run=s.expedition.afterlight;
  if(id==='afterlight-board'){
   if(stage===0){mark(s,AFTERLIGHT_FLAGS[0]);s.expedition.tracked='afterlight';s.checkpoint='bellmarket';emit(s,'save');say(s,'IONA: The market has lost its public lighting circuit. Recover the sealed fuse, repair the Arcade relays and restart the Theatre broadcast. '+AFTERLIGHT_HINTS[1]);}
   else if(stage===4){reward(s,'afterlight');emit(s,'afterlight-restored');say(s,'IONA: Listen. The market bells are answering again. Every open shop can find its way home. Bellwether Afterlight is complete; 240 credits are saved.');emit(s,'afterlight-ending');}
   else say(s,AFTERLIGHT_HINTS[stage]);
   return true;
  }
  if(stage===0){say(s,'Read the Afterlight dispatch by the Bellwether arrival before using this equipment.');return true;}
  if(id==='afterlight-clue'){say(s,'ELECTRICIAN\'S PLATE: Relay A needs THREE ticks; B needs ONE; C needs TWO. Recover the fuse first. Set 3, 1, 2 from west to east, then use the test cabinet.');emit(s,'afterlight-note');return true;}
  if(id==='afterlight-fuse'){
   if(stage!==1){say(s,'The recovered fuse is already recorded in your expedition.');return true;}
   if(run.kind==='street'&&run.cleared){clearActors(s);s.expedition.afterlight=blank();mark(s,AFTERLIGHT_FLAGS[1]);s.p.health=Math.min(100,s.p.health+30);s.p.energy=Math.min(100,s.p.energy+30);emit(s,'save');emit(s,'afterlight-step',{stage:2});say(s,'Fuse recovered. The crate also held a single field dressing and capacitor. '+AFTERLIGHT_HINTS[2]);}
   else if(!run.active){spawn(s,'street');say(s,'Two Registry guards contest the sealed fuse. Defeat them, then collect it with another interaction.');}
   else say(s,'Clear the two fuse guards before collecting: '+living(s).length+' remain.');
   return true;
  }
  if(id.startsWith('afterlight-dial-')||id==='afterlight-test'){
   if(stage!==2){say(s,stage<2?'Recover the guarded fuse before powering the switchboard.':'The Arcade circuit is stable. '+AFTERLIGHT_HINTS[stage]);return true;}
   if(id==='afterlight-test'){if(s.expedition.afterlightDials.every((v,i)=>v===AFTERLIGHT_CODE[i])){mark(s,AFTERLIGHT_FLAGS[2]);emit(s,'afterlight-step',{stage:3});say(s,'Circuit accepted. '+AFTERLIGHT_HINTS[3]);}else{emit(s,'afterlight-error');say(s,'The test fails safely. Read the plate: A=3, B=1, C=2. Your dial positions remain saved.');}}
   else{const i=Number(id.at(-1));if(!Number.isInteger(i)||i<0||i>2)return false;s.expedition.afterlightDials[i]=(s.expedition.afterlightDials[i]+1)%4;emit(s,'afterlight-dial',{index:i,value:s.expedition.afterlightDials[i]});emit(s,'save');say(s,'Arcade relay '+['A','B','C'][i]+': '+s.expedition.afterlightDials[i]+' ticks. Plate settings are A=3, B=1, C=2.');}return true;
  }
  if(id==='afterlight-beacon'){
   if(stage!==3){say(s,stage<3?'The rooftop transmitter needs the repaired Arcade circuit.':AFTERLIGHT_HINTS[stage]);return true;}
   if(!run.active){spawn(s,'roof');say(s,'Broadcast charging. Hold the Theatre roof for 20 seconds and clear both boarding guards. Leaving the rooftop interrupts the attempt, not your saved repairs.');}
   else say(s,'Hold the roof: '+Math.min(20,Math.floor(run.time))+'/20 seconds, '+living(s).length+' guards remain.');return true;
  }
  return false;
 }
 function tick(s,dt){const run=s.expedition.afterlight;if(!run?.active)return;const p=s.p,roof=run.kind==='roof',inside=roof?Math.abs(p.x+107)<8&&Math.abs(p.z+9)<9&&Math.abs(p.y-27.5)<6:Math.abs(p.x+93)<27&&Math.abs(p.z+18)<23&&Math.abs(p.y-7)<6;
  if(!inside){abort(s,'abandoned');return;}run.time+=dt;
  if(living(s).length)return;
  if(!roof){if(!run.cleared){run.cleared=true;emit(s,'afterlight-step',{stage:1});say(s,'Fuse guards cleared. Use the sealed fuse to collect it.');}return;}
  if(run.time>=20){mark(s,AFTERLIGHT_FLAGS[3]);clearActors(s);s.expedition.afterlight=blank();emit(s,'afterlight-step',{stage:4});say(s,'The Theatre signal is live. '+AFTERLIGHT_HINTS[4]);}
 }
 function killed(s,b){if(!b.afterlight)return false;if(b.credited)return true;b.credited=true;b.hp=0;s.stats.defeated++;emit(s,'defeat',{id:b.id,at:{x:b.x,y:b.y,z:b.z}});return true;}
 return{init,handle,tick,abort,killed};
}
